using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class RefineWardens {
 const string Dir="Assets/Resources/ExpeditionEnemies/";
 static Material Mat(string name,Color tint,bool glow=false){var path=Dir+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",tint);m.SetFloat("_Smoothness",.18f);m.SetFloat("_Metallic",.1f);if(glow){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",tint*2);}return m;}
 static Mesh Save(Mesh mesh,string name){string path=Dir+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.vertices=mesh.vertices;old.triangles=mesh.triangles;old.normals=mesh.normals;old.RecalculateBounds();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static GameObject MeshPart(Transform parent,string name,Mesh mesh,Material mat,Vector3 pos,Vector3 scale){var go=new GameObject(name);go.transform.SetParent(parent,false);go.transform.localPosition=pos;go.transform.localScale=scale;go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=mat;return go;}
 static Mesh Rock(){float t=(1+Mathf.Sqrt(5))/2;var v=new[]{new Vector3(-1,t,0),new Vector3(1,t,0),new Vector3(-1,-t,0),new Vector3(1,-t,0),new Vector3(0,-1,t),new Vector3(0,1,t),new Vector3(0,-1,-t),new Vector3(0,1,-t),new Vector3(t,0,-1),new Vector3(t,0,1),new Vector3(-t,0,-1),new Vector3(-t,0,1)};int[] idx={0,11,5,0,5,1,0,1,7,0,7,10,0,10,11,1,5,9,5,11,4,11,10,2,10,7,6,7,1,8,3,9,4,3,4,2,3,2,6,3,6,8,3,8,9,4,9,5,2,4,11,6,2,10,8,6,7,9,8,1};var m=new Mesh();m.vertices=idx.Select(i=>v[i].normalized).ToArray();m.triangles=Enumerable.Range(0,60).ToArray();m.RecalculateNormals();return Save(m,"Warden faceted stone");}
 static Mesh Blade(){var v=new[]{new Vector3(-.12f,0,-.035f),new Vector3(.12f,0,-.035f),new Vector3(.16f,.85f,-.015f),new Vector3(0,1.15f,0),new Vector3(-.08f,.9f,-.015f),new Vector3(-.12f,0,.035f),new Vector3(.12f,0,.035f),new Vector3(.16f,.85f,.015f),new Vector3(-.08f,.9f,.015f)};var m=new Mesh{vertices=v,triangles=new[]{0,2,1,0,4,2,4,3,2,5,6,7,5,7,8,8,7,3,0,1,6,0,6,5,1,2,7,1,7,6,2,3,7,4,8,3,0,5,8,0,8,4}};m.RecalculateNormals();return Save(m,"Warden forged blade");}
 public static string Run(){var blade=Blade();var rock=Rock();var steel=Mat("Acero ennegrecido",new Color(.19f,.23f,.25f));var stone=Mat("Obsidiana tallada",new Color(.12f,.15f,.18f));var gem=Mat("Nucleo espectral",new Color(.08f,.65f,.8f),true);foreach(var name in new[]{"Custodio de las dos hojas","Lancero de ceniza"}){string path=Dir+name+".prefab";var go=PrefabUtility.LoadPrefabContents(path);try{var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/01_Prefabs/Bosses/MonsterOrc.prefab").GetComponentsInChildren<SkinnedMeshRenderer>();var skins=go.GetComponentsInChildren<SkinnedMeshRenderer>();for(int i=0;i<skins.Length&&i<source.Length;i++){var originals=source[i].sharedMaterials;var mapped=new Material[originals.Length];for(int j=0;j<originals.Length;j++){var original=originals[j];var material=Mat(name+" textura "+j,new Color(.65f,.65f,.65f));var texture=original.HasProperty("_BaseMap")?original.GetTexture("_BaseMap"):original.HasProperty("_MainTex")?original.GetTexture("_MainTex"):null;material.SetTexture("_BaseMap",texture);EditorUtility.SetDirty(material);mapped[j]=material;}skins[i].sharedMaterials=mapped;}foreach(var t in go.GetComponentsInChildren<Transform>().Where(t=>t.name=="Hoja"||t.name=="Punta").ToArray()){var parent=t.parent;var pos=t.name=="Hoja"?Vector3.up*.08f:Vector3.up*1.15f;var scale=t.name=="Hoja"?Vector3.one:new Vector3(.7f,.48f,.8f);UnityEngine.Object.DestroyImmediate(t.gameObject);MeshPart(parent,"Acero forjado",blade,steel,pos,scale);}PrefabUtility.SaveAsPrefabAsset(go,path);}finally{PrefabUtility.UnloadPrefabContents(go);}}
 string guardianPath=Dir+"Guardian de obsidiana.prefab";var guardian=PrefabUtility.LoadPrefabContents(Dir+"Custodio de las dos hojas.prefab");try{guardian.name="Guardian de obsidiana";var boss=guardian.GetComponent<Codice.Bosses.BossCharacter>();boss.kind=Codice.Bosses.BossKind.StoneGuardian;boss.baseHealth=1700;foreach(var r in guardian.GetComponentsInChildren<Renderer>())r.enabled=false;var bones=guardian.GetComponentsInChildren<Transform>();string[] names={"spine","chest","head","upper_arm.L","upper_arm.R","forearm.L","forearm.R","thigh.L","thigh.R","shin.L","shin.R","hand.L","hand.R","foot.L","foot.R"};int count=0;foreach(var bone in bones){string lower=bone.name.ToLowerInvariant();Vector3 size;if(lower=="spine.006")size=new Vector3(.3f,.38f,.3f);else if(lower=="spine"||lower=="spine.001"||lower=="spine.002"||lower=="spine.003")size=new Vector3(.52f,.42f,.35f);else if(lower=="upper_arm.l"||lower=="upper_arm.r"||lower=="forearm.l"||lower=="forearm.r"||lower=="thigh.l"||lower=="thigh.r"||lower=="shin.l"||lower=="shin.r")size=new Vector3(.27f,.42f,.28f);else if(lower=="hand.l"||lower=="hand.r")size=new Vector3(.32f,.3f,.3f);else if(lower=="foot.l"||lower=="foot.r")size=new Vector3(.25f,.2f,.4f);else continue;float scale=1/Mathf.Max(.01f,bone.lossyScale.x);var segment=MeshPart(bone,"Piedra segmentada",rock,stone,Vector3.zero,size*scale);segment.transform.rotation=Quaternion.identity;if(lower=="spine.006"){var eye=MeshPart(bone,"Ojo del guardián",rock,gem,Vector3.zero,new Vector3(.17f,.065f,.07f)*scale);eye.transform.position=bone.position+new Vector3(0,.07f,.28f);eye.transform.rotation=Quaternion.identity;}count++;}if(count<8)throw new Exception("Guardian skeleton insufficient: "+count);PrefabUtility.SaveAsPrefabAsset(guardian,guardianPath);}finally{PrefabUtility.UnloadPrefabContents(guardian);}AssetDatabase.SaveAssets();return "Textured wardens, forged blades, articulated stone guardian";}
}
